# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: emit
def emit(xs, offset=1):
    return [v + offset for v in xs[1:]]

# region: render
def render(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: fold
def fold(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return fold(digest(intake(render(emit(shape(raw))))))

